syntax:
template <class T> struct remove_extent; // removes the first array dimension from type T
// Specializations for array types:
// template <class U, std::size_t N> struct remove_extent<U[N]> { using type = U; };
// template <class U> struct remove_extent<U[]> { using type = U; };
// Helper alias:
template <class T> using remove_extent_t = typename remove_extent<T>::type;

code_example:
#include <type_traits>
#include <cassert>

int main() {
    static_assert(std::is_same<remove_extent_t<int>, int>::value, "Failed for int");
    static_assert(std::is_same<remove_extent_t<int[2]>, int>::value, "Failed for int[2]");
    static_assert(std::is_same<remove_extent_t<int[2][3]>, int[3]>::value, "Failed for int[2][3]");
    static_assert(std::is_same<remove_extent_t<int[][3]>, int[3]>::value, "Failed for int[][3]");
}
